  function updateGradescopeIdentity(){const course=state.gsCourse;if(!course)return;$('#gcsi-gs-course').textContent=[course.code,course.name].filter(Boolean).join(' — ')||`Course #${courseId}`;const term=$('#gcsi-gs-term');term.textContent=course.term||'';term.hidden=!course.term;}
