    walk(parseJsonAttr(card),obj=>{if(!term)term=semesterIn(`${obj.semester||''} ${obj.year||''} ${obj.term||''}`);});
    for(let node=card;node&&!term;node=node.parentElement){term=semesterIn(node.getAttribute?.('data-term')||node.getAttribute?.('aria-label'));if(term)break;let sibling=node.previousElementSibling;while(sibling&&!term){term=semesterIn(sibling.matches?.('h1,h2,h3,h4,[class*="term" i]')?sibling.textContent:'');sibling=sibling.previousElementSibling;}}
    if(!term){const headings=[...doc.querySelectorAll('h1,h2,h3,h4,[class*="term" i]')].filter(node=>(node.compareDocumentPosition(card)&Node.DOCUMENT_POSITION_FOLLOWING)&&semesterIn(node.textContent));term=semesterIn(headings.at(-1)?.textContent);}
